package com.priperi;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** BIP39 English 256-bit entropy + 8-bit checksum; never a permanent recovery seed. */
final class TransferPhrase {
 private static final String PREFIX="priperi-transfer-v1:";
 private final String[] words;private final Map<String,Integer> indexes=new HashMap<>();
 TransferPhrase(InputStream input)throws IOException{try(BufferedReader reader=new BufferedReader(new InputStreamReader(input,StandardCharsets.US_ASCII))){List<String> list=new ArrayList<>();String line;while((line=reader.readLine())!=null){if(list.size()>=2048||!line.matches("[a-z]{3,8}"))throw new IOException("Invalid transfer word list");list.add(line);}if(list.size()!=2048)throw new IOException("Incomplete transfer word list");words=list.toArray(new String[0]);for(int i=0;i<words.length;i++)if(indexes.put(words[i],i)!=null)throw new IOException("Duplicate transfer word");}}
 static byte[] fresh(){byte[] entropy=new byte[32];new SecureRandom().nextBytes(entropy);return entropy;}
 String encode(byte[] entropy)throws GeneralSecurityException{if(entropy.length!=32)throw new GeneralSecurityException("Invalid transfer entropy");byte[] bits=Arrays.copyOf(entropy,33);bits[32]=MessageDigest.getInstance("SHA-256").digest(entropy)[0];StringJoiner out=new StringJoiner(" ");for(int word=0;word<24;word++){int n=0;for(int bit=word*11;bit<(word+1)*11;bit++)n=(n<<1)|((bits[bit/8]>>(7-bit%8))&1);out.add(words[n]);}Arrays.fill(bits,(byte)0);return out.toString();}
 byte[] decode(String phrase)throws GeneralSecurityException{if(phrase==null||phrase.length()>512)throw new GeneralSecurityException("Enter all 24 transfer words.");if(phrase.startsWith(PREFIX))phrase=phrase.substring(PREFIX.length());String[] parts=phrase.trim().toLowerCase(Locale.ROOT).split("\\s+");if(parts.length!=24)throw new GeneralSecurityException("Enter all 24 transfer words in order.");byte[] bits=new byte[33];for(int i=0;i<24;i++){Integer n=indexes.get(parts[i]);if(n==null)throw new GeneralSecurityException("Check the transfer words for a typing mistake.");for(int j=0;j<11;j++){int bit=i*11+j;bits[bit/8]|=((n>>(10-j))&1)<<(7-bit%8);}}byte[] entropy=Arrays.copyOf(bits,32);byte checksum=MessageDigest.getInstance("SHA-256").digest(entropy)[0];if(checksum!=bits[32]){Arrays.fill(entropy,(byte)0);throw new GeneralSecurityException("The transfer words do not pass their checksum. Check their order.");}Arrays.fill(bits,(byte)0);return entropy;}
 String qr(byte[] entropy)throws GeneralSecurityException{return PREFIX+encode(entropy);}
}
